            if (w + A <= maxW) can_w[w + A] = 1;
            if (w + B <= maxW) can_w[w + B] = 1;
        }
    }

    can_s[0] = 1;
    for (int s = 0; s <= F; s++) {
        if (can_s[s]) {
            if (s + C <= F) can_s[s + C] = 1;
            if (s + D <= F) can_s[s + D] = 1;
        }
    }

    best_s[0] = 0;
    for (int x = 1; x <= F; x++) {
        best_s[x] = can_s[x] ? x : best_s[x-1];
    }

    // Find best density
    long long best_num = 0, best_den = 1; // best sugar/total as fraction
    int ans_water = 0, ans_sugar = 0;

    for (int w = 0; w <= maxW; w++) {
        if (!can_w[w]) continue;
        int water = 100 * w;
        int max_sugar = w * E;
        if (water + max_sugar > F) max_sugar = F - water;
        if (max_sugar < 0) continue;
        int s = best_s[max_sugar];
        // density = s / (water + s), compare with best_num/best_den
        // s * best_den > best_num * (water + s)
        long long lhs = (long long)s * best_den;
        long long rhs = (long long)best_num * (water + s);
        if (lhs > rhs) {
            best_num = s;
            best_den = water + s;
            ans_water = water;
            ans_sugar = s;
        }
    }

    printf("%d %d\n", ans_water + ans_sugar, ans_sugar);
    return 0;
