    for (int i = 0; i <= F; i++) {
        if (!sugar[i]) continue;
        if (i + C <= F) sugar[i + C] = true;
        if (i + D <= F) sugar[i + D] = true;
    }

    int bestTotal = 100 * A; // any valid answer accepted; will be updated
    int bestSugar = 0;

    for (int w = 100; w <= F; w++) {
        if (!water[w]) continue;

