using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int A, B, C, D, E, F;
    cin >> A >> B >> C >> D >> E >> F;

    // Precompute possible water amounts (multiples of 100)
    // Max water = F (but we need at least some water to dissolve sugar?)
    // Actually water is in multiples of 100, up to F.
    vector<int> water_amt;
    for (int i = 0; i * 100 * A <= F; ++i) {
        for (int j = 0; j * 100 * B <= F - i * 100 * A; ++j) {
            int w = i * 100 * A + j * 100 * B;
            if (w <= F) water_amt.push_back(w);
        }
    }
    sort(water_amt.begin(), water_amt.end());
    water_amt.erase(unique(water_amt.begin(), water_amt.end()), water_amt.end());

    int best_sugar = 0, best_total = 0;
    // For each possible water amount, find max sugar that can be dissolved
    for (int w : water_amt) {
        if (w == 0) continue; // need water to dissolve sugar
        int max_sugar_dissolve = w / 100 * E; // max sugar that can dissolve in w water
        // Now find the maximum sugar <= max_sugar_dissolve that we can make using C and D
        // We can use at most max_sugar_dissolve grams of sugar
        int limit = min(max_sugar_dissolve, F - w);
        int best_for_this_water = 0;
        // Iterate over possible number of C and D operations
        for (int ci = 0; ci * C <= limit; ++ci) {
            int remaining = limit - ci * C;
            int dj = remaining / D;
            int sugar = ci * C + dj * D;
            if (sugar > best_for_this_water) {
                best_for_this_water = sugar;
            }
        }
        // Now compare density: sugar / (water + sugar)
        // To avoid floating point, compare cross multiplication:
        // best_sugar / best_total  <  best_for_this_water / (w + best_for_this_water)
        // => best_sugar * (w + best_for_this_water) < best_for_this_water * best_total
        long long left = 1LL * best_sugar * (w + best_for_this_water);
        long long right = 1LL * best_for_this_water * best_total;
        if (best_total == 0 || left < right) {
            best_sugar = best_for_this_water;
            best_total = w + best_for_this_water;
        }
    }

    // If best_total is 0, we output 0 0 (pure water case already covered? Actually we might have water but no sugar)
    // The problem allows pure water.
    // In our loops we start with best_sugar=0, best_total=0, but we never set best_total to water only.
    // So we need to also consider pure water with any water amount.
    // Let's find the maximum water amount <= F (pure water) as a candidate.
    int max_water = 0;
    for (int w : water_amt) {
        if (w > max_water) max_water = w;
    }
    // Compare pure water density: 0 / max_water vs best_sugar / best_total
    // Since 0 < any positive density, we only need to consider if best_total == 0
    if (best_total == 0) {
        best_total = max_water;
        best_sugar = 0;
    }

    cout << best_total << " " << best_sugar << "\n";

    return 0;
}

