int main(){
    long long A,B,C,D,E,F;
    cin>>A>>B>>C>>D>>E>>F;

    long long best_num=0, best_den=1; // best sugar/total as fraction
    long long ans_total=0, ans_sugar=0;

    auto canWater = [&](long long w) -> bool {
        if(w==0) return true;
        long long a=100*A, b=100*B;
        for(long long i=0; i*a<=w; i++)
            if((w-i*a)%b==0) return true;
        return false;
    };
    auto canSugar = [&](long long s) -> bool {
        if(s==0) return true;
        for(long long k=0; k*C<=s; k++)
            if((s-k*C)%D==0) return true;
        return false;
    };

    long long gw = __gcd(100*A, 100*B);
    long long gs = __gcd(C, D);

    for(long long w=0; w<=F; w+=gw){
        if(!canWater(w)) continue;
        long long max_s = min(E*w/100, F-w);
        // find largest s <= max_s that's multiple of gs and canSugar
        long long s = (max_s/gs)*gs;
        for(; s>=0; s-=gs){
            if(canSugar(s)){
                if(w==0 && s==0) break;
                if(w==0) break; // can't dissolve sugar without water
                // compare s/(w+s) > best_num/best_den
                if(s*best_den > best_num*(w+s)){
                    best_num=s; best_den=w+s;
                    ans_total=w+s; ans_sugar=s;
                }
                break;
            }
            if(s==0) break;
        }
    }
    cout<<ans_total<<" "<<ans_sugar<<endl;
}

