import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int A = fs.nextInt();
        int B = fs.nextInt();
        int C = fs.nextInt();
        int D = fs.nextInt();
        int E = fs.nextInt();
        int F = fs.nextInt();

        boolean[] waterPossible = new boolean[F + 1];
        boolean[] sugarPossible = new boolean[F + 1];

        waterPossible[0] = true;
        for (int i = 0; i <= F; i++) {
            if (!waterPossible[i]) continue;
            if (i + 100 * A <= F) waterPossible[i + 100 * A] = true;
            if (i + 100 * B <= F) waterPossible[i + 100 * B] = true;
        }

        sugarPossible[0] = true;
        for (int i = 0; i <= F; i++) {
            if (!sugarPossible[i]) continue;
            if (i + C <= F) sugarPossible[i + C] = true;
            if (i + D <= F) sugarPossible[i + D] = true;
        }

        List<Integer> sugars = new ArrayList<>();
        for (int i = 0; i <= F; i++) {
            if (sugarPossible[i]) sugars.add(i);
        }

        int bestTotal = 100 * A; // fallback, but will be updated by valid states
        int bestSugar = 0;
        boolean found = false;

        for (int water = 1; water <= F; water++) {
            if (!waterPossible[water]) continue;

            int maxSugarBySolubility = water * E / 100;
            int maxSugarByCapacity = F - water;
            int maxSugar = Math.min(maxSugarBySolubility, maxSugarByCapacity);

            int sugar = 0;
            for (int s : sugars) {
                if (s <= maxSugar) sugar = s;
                else break;
            }

            int total = water + sugar;

            if (!found) {
                bestTotal = total;
                bestSugar = sugar;
                found = true;
            } else {
                // Compare density: sugar/total
                long lhs = (long) sugar * bestTotal;
                long rhs = (long) bestSugar * total;
                if (lhs > rhs) {
                    bestTotal = total;
                    bestSugar = sugar;
                }
            }
        }

        if (!found) {
            // Should not happen under normal constraints, but keep safe.
            System.out.println("0 0");
        } else {
            System.out.println(bestTotal + " " + bestSugar);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

def solve():
    import sys
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    A, B, C, D, E, F = map(int, input_data)

    # Possible water masses: multiples of 100A and 100B
    water_set = set()
    for i in range(0, F // (100 * A) + 1):
        for j in range(0, (F - 100 * A * i) // (100 * B) + 1):
            water = 100 * A * i + 100 * B * j
            if water <= F:
                water_set.add(water)

    # Possible sugar masses: multiples of C and D
    sugar_set = set()
    max_sugar = F  # sugar mass cannot exceed total mass
    for i in range(0, max_sugar // C + 1):
        for j in range(0, (max_sugar - C * i) // D + 1):
            sugar = C * i + D * j
            if sugar <= max_sugar:
                sugar_set.add(sugar)

    best_density = -1.0
    best_water = 0
    best_sugar = 0

    for water in water_set:
        if water == 0:
            continue
        # max sugar that can dissolve in this water
        max_dissolvable = (E * water) // 100
        for sugar in sugar_set:
            if sugar > max_dissolvable:
                continue
            total = water + sugar
            if total > F:
                continue
            density = 100.0 * sugar / total
            if density > best_density:
                best_density = density
                best_water = water
                best_sugar = sugar

    # If no sugar water found, output pure water (any valid water)
    if best_density < 0:
        # output any valid water, e.g., 100*A if possible, else 0
        if water_set:
            best_water = min(water_set)
        else:
            best_water = 0
        best_sugar = 0

    print(best_water + best_sugar, best_sugar)

if __name__ == "__main__":
    solve()
